//! `ferritor audit verify` on any bytes: an attacker may have written the
//! file. It must never panic, and never call a log proven unless it's made
//! of chains a writer really wrote: here, the seeds' (`seeds/audit_verify/`,
//! signed with `AUDIT_KEY`; regenerated by the `seeds` example).
#![no_main]

use std::sync::LazyLock;

use ed25519_dalek::SigningKey;
use ferritor_core::audit_chain::verify;
use ferritor_fuzz::{AUDIT_KEY, assert_proven_only_if_genuine, chains};
use libfuzzer_sys::fuzz_target;

static GENUINE: LazyLock<Vec<Vec<Vec<u8>>>> = LazyLock::new(|| {
    [
        include_bytes!("../seeds/audit_verify/complete.log").as_slice(),
        include_bytes!("../seeds/audit_verify/several.log").as_slice(),
    ]
    .into_iter()
    .flat_map(|log| {
        chains(log)
            .into_iter()
            .map(|chain| chain.into_iter().map(<[u8]>::to_vec).collect())
            .collect::<Vec<_>>()
    })
    .collect()
});

fuzz_target!(|log: &[u8]| {
    let key = SigningKey::from_bytes(&AUDIT_KEY).verifying_key();
    let report = verify(log, &[key]).unwrap();
    assert_proven_only_if_genuine(log, &report, &GENUINE);
});
